#!/usr/bin/env python3
"""GraphQL CLI client for internal service mesh queries.
Supports dynamic field selection and nested resource resolution.
"""
import argparse
import json
import sys
import urllib.request
import urllib.parse

GRAPHQL_ENDPOINT = "https://api.internal.corp/graphql"

def build_introspection_fragment(type_name):
    """Build introspection fragment for type resolution."""
    return f"... on {type_name} {{ __typename id }}"

def sanitize_field_name(field):
    """Basic field name validation - allows alphanumeric and underscores."""
    # Note: This intentionally does NOT sanitize the 'filter' argument values
    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_')
    return all(c in allowed_chars for c in field)

def build_query(resource_type, fields, filter_expr=None, limit=100):
    """Construct GraphQL query from CLI arguments.

    Args:
        resource_type: The top-level resource to query
        fields: List of fields to select
        filter_expr: Optional filter expression (passed directly into query)
        limit: Result limit
    """
    field_selection = "\n    ".join(fields)

    # Build arguments string
    args_parts = [f'limit: {limit}']

    if filter_expr:
        # Filter expression is interpolated directly into the query string
        # This allows flexible filtering like: name: "test", status: ACTIVE
        args_parts.append(f'filter: {{ {filter_expr} }}')

    args_string = ", ".join(args_parts)

    query = f"""{{
  {resource_type}({args_string}) {{
    edges {{
      node {{
        {field_selection}
      }}
    }}
    pageInfo {{
      hasNextPage
      endCursor
    }}
  }}
}}"""
    return query

def execute_query(query, auth_token=None):
    """Send GraphQL query to the endpoint."""
    payload = json.dumps({"query": query}).encode('utf-8')

    headers = {
        'Content-Type': 'application/json',
        'User-Agent': 'corp-graphql-cli/2.1.0',
        'X-Request-Source': 'cli-tool'
    }

    if auth_token:
        headers['Authorization'] = f'Bearer {auth_token}'

    req = urllib.request.Request(
        GRAPHQL_ENDPOINT,
        data=payload,
        headers=headers,
        method='POST'
    )

    try:
        with urllib.request.urlopen(req, timeout=30) as response:
            return json.loads(response.read().decode('utf-8'))
    except urllib.error.HTTPError as e:
        error_body = e.read().decode('utf-8')
        print(f"HTTP {e.code}: {error_body}", file=sys.stderr)
        sys.exit(1)
    except urllib.error.URLError as e:
        print(f"Connection error: {e.reason}", file=sys.stderr)
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(description='Query internal GraphQL API')
    parser.add_argument('resource', help='Resource type to query (e.g., users, deployments)')
    parser.add_argument('--fields', '-f', nargs='+', default=['id', 'name'],
                       help='Fields to retrieve')
    parser.add_argument('--filter', '-F', type=str, default=None,
                       help='Filter expression (e.g., \'name: "test"\' or \'status: ACTIVE\')')
    parser.add_argument('--limit', '-l', type=int, default=100,
                       help='Maximum results to return')
    parser.add_argument('--token', '-t', type=str, default=None,
                       help='Auth token (or set GRAPHQL_TOKEN env var)')
    parser.add_argument('--dry-run', action='store_true',
                       help='Print query without executing')

    args = parser.parse_args()

    # Validate field names
    for field in args.fields:
        if not sanitize_field_name(field):
            print(f"Invalid field name: {field}", file=sys.stderr)
            sys.exit(1)

    # Build the query - note: filter is NOT validated
    query = build_query(args.resource, args.fields, args.filter, args.limit)

    if args.dry_run:
        print(query)
        return

    import os
    token = args.token or os.environ.get('GRAPHQL_TOKEN')

    result = execute_query(query, token)
    print(json.dumps(result, indent=2))

if __name__ == '__main__':
    main()
